<?php
require 'config.php'; require_role('student'); require_once 'pdf_helper.php';
$u=$_SESSION['user']; $term=selected_term($pdo); $termId=$term?(int)$term['id']:0;
$q=$pdo->prepare("SELECT s.*,sub.code,sub.name,sub.units,o.section,f.name AS faculty_name FROM schedules s JOIN subjects sub ON sub.id=s.subject_id LEFT JOIN subject_offerings o ON o.subject_id=s.subject_id AND o.day_name=s.day_name AND o.start_time=s.start_time AND o.end_time=s.end_time AND o.room=s.room LEFT JOIN users f ON f.id=COALESCE(o.faculty_id,sub.faculty_id) WHERE s.student_id=? AND s.term_id=? ORDER BY FIELD(s.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),s.start_time");
$q->execute([$u['id'],$termId]); $rows=$q->fetchAll(); $units=array_sum(array_map(fn($r)=>(int)$r['units'],$rows));
$pdf=new ETW_PDF(); $pdf->addPage();
$pdf->setFill(0.06,0.17,0.42); $pdf->rect(0,744,612,48,true); $pdf->image(__DIR__.'/nu-logo.jpg',36,660,58,70);
$pdf->setFill(0.08,0.12,0.22); $pdf->text(36,635,'CERTIFICATE OF REGISTRATION',18,true); $pdf->text(36,617,'ETW – NU Baliwag Online Management System',9,false);
$y=586; $pdf->setFill(0.08,0.12,0.22);
$meta=[['Academic Term',$term['label']??'Academic Term'],['Student',$u['name']],['Student ID',$u['student_id']?:'—'],['Program',$u['program']?:'—'],['Total Units',(string)$units]];
foreach($meta as $m){$pdf->text(36,$y,$m[0].':',9,true);$pdf->text(145,$y,$m[1],9,false);$y-=18;}
$y-=8; $pdf->setFill(0.94,0.96,0.98);$pdf->rect(36,$y-18,540,26,true);$pdf->setFill(0.08,0.12,0.22);
$cols=[36,155,205,285,405,576];$heads=['Subject','Units','Schedule','Teacher','Section / Room'];foreach($heads as $i=>$h)$pdf->text($cols[$i]+4,$y-8,$h,8,true);$y-=38;
foreach($rows as $r){if($y<95){$pdf->addPage();$y=735;$pdf->setFill(0.08,0.12,0.22);$pdf->text(36,755,'CERTIFICATE OF REGISTRATION — CONTINUED',12,true);$pdf->setFill(0.94,0.96,0.98);$pdf->rect(36,$y-18,540,26,true);$pdf->setFill(0.08,0.12,0.22);foreach($heads as $i=>$h)$pdf->text($cols[$i]+4,$y-8,$h,8,true);$y-=38;}
  $subject=$r['code'].' — '.$r['name'];$sched=$r['day_name'].', '.date('g:i A',strtotime($r['start_time'])).'–'.date('g:i A',strtotime($r['end_time']));$teacher=$r['faculty_name']??'Assigned Faculty';$room=($r['section']??'—').' / '.$r['room'];
  $vals=[$subject,(string)$r['units'],$sched,$teacher,$room];$max=[16,5,18,17,20];$lineCount=max(array_map('count',array_map(fn($v,$i)=>etw_pdf_wrap($v,$max[$i]),$vals,array_keys($vals))));
  $wrapped=[];foreach($vals as $i=>$v)$wrapped[$i]=etw_pdf_wrap($v,$max[$i]);$rowH=max(20,$lineCount*10+6);$pdf->setStroke(0.82,0.85,0.9);$pdf->line(36,$y-$rowH,576,$y-$rowH);foreach($wrapped as $i=>$lines){foreach($lines as $j=>$line)$pdf->text($cols[$i]+4,$y-10-($j*10),$line,7,false);} $y-=$rowH;
}
$pdf->setFill(0.08,0.12,0.22);$y=max(55,$y-18);$pdf->text(36,$y,'This is a prototype Certificate of Registration generated by ETW – NU Baliwag Online Management System.',7,false);$pdf->text(36,$y-13,'For demonstration purposes only.',7,false);
$filename='ETW_Certificate_of_Registration_'.preg_replace('/[^A-Za-z0-9_-]/','_',($term['term_key']??'term')).'.pdf';
$out=$pdf->output(); header('Content-Type: application/pdf'); header('Content-Disposition: attachment; filename="'.$filename.'"'); header('Content-Length: '.strlen($out)); echo $out; exit;
